inline const Transcript& get(const std::string& name) {
    int count = 0;
    const Transcript* data = all(count);
    for (int i = 0; i < count; ++i)
        if (name == data[i].name) return data[i];
    throw std::runtime_error("no golden transcript " + name);
}

